// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 _changeFee) public {
        // Bound to a valid fee range, excluding 0 to ensure the bug is detectable
        vm.assume(_changeFee > 0);
        vm.assume(_changeFee <= type(uint56).max);

        // Initialize with the fuzzed changeFee
        c.initialize(
            address(0),
            address(0),
            1,
            1,
            _changeFee,
            500,
            bytes32(0),
            false,
            false
        );

        // The universal rule: changeFee must equal the passed _changeFee
        assertEq(c.changeFee(), _changeFee);
    }
}

